/* Independent adapters using the public service contracts also used by Folia.
   No Folia source is incorporated. See SOURCES.md for protocol references. */
(function(global){
'use strict';
const names={netease:'网易云音乐',qq:'QQ 音乐',kugou:'酷狗音乐',navidrome:'Navidrome'};
const sessions={};let anonymousPromise=null;
function stored(key,fallback){try{return JSON.parse(localStorage.getItem('sonora:'+key))??fallback}catch{return fallback}}
let configs=stored('sources',{});if(!configs.netease&&stored('musicEndpoint',''))configs.netease={endpoint:stored('musicEndpoint','')};
function endpoint(raw){const u=new URL(raw);const loop=['localhost','127.0.0.1','[::1]'].includes(u.hostname);if(u.protocol!=='https:'&&!(loop&&u.protocol==='http:'&&location.protocol==='http:'))throw Error('线上服务使用 HTTPS；本机 HTTP 服务只能在本机预览中使用');if(u.username||u.password||u.search||u.hash)throw Error('地址中请勿包含账号、密码或查询参数');return u.href.replace(/\/$/,'')}
function configure(provider,raw){if(!names[provider])throw Error('未知音乐源');const base=endpoint(raw);if(configs[provider]?.endpoint!==base)delete sessions[provider];configs[provider]={endpoint:base};localStorage.setItem('sonora:sources',JSON.stringify(configs));if(provider==='netease')localStorage.setItem('sonora:musicEndpoint',JSON.stringify(base));return base}
async function json(url,opts={}){const r=await fetch(url,{...opts,signal:opts.signal||AbortSignal.timeout(20000)});if(!r.ok)throw Error(r.status===401?'需要登录或登录已过期':'音乐服务返回 HTTP '+r.status);return r.json()}
function base(p){if(!configs[p]?.endpoint)throw Error('请先连接'+names[p]+'的音乐服务');return configs[p].endpoint}
async function request(p,path,args={},options={}){if(p==='netease'&&!sessions.netease?.cookie&&!/^\/(login|logout|register)/.test(path)){if(!anonymousPromise){const origin=base(p);anonymousPromise=request('netease','/register/anonimous').then(d=>{if(base(p)===origin&&d.cookie&&!sessions.netease?.cookie)sessions.netease={cookie:d.cookie,anonymous:true}}).catch(()=>{}).finally(()=>anonymousPromise=null)}await anonymousPromise}const url=new URL(base(p)+path);const session=sessions[p];let d;if(p==='netease'){const payload=new URLSearchParams({...args,timestamp:Date.now(),...(session?.cookie?{cookie:session.cookie}:{})});d=await json(url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:payload.toString()})}else{Object.entries(args).forEach(([k,v])=>v!==undefined&&url.searchParams.set(k,String(v)));d=await json(url,{credentials:'omit',...options,...(p==='qq'&&session?.token?{headers:{'X-QQ-Session':session.token,...options.headers}}:{})})}if(p==='netease'&&d.code&&![200,800,801,802,803].includes(Number(d.code)))throw Error(d.message||d.msg||'网易云请求未成功');return d}
function secureUrl(url){if(typeof url!=='string')return '';try{const u=new URL(url,location.href);if(!['http:','https:','blob:'].includes(u.protocol))return '';return location.protocol==='https:'?u.href.replace(/^http:/,'https:'):u.href}catch{return ''}}
function normalize(p,s){const n={provider:p,mediaId:String(s.id??''),artist:'未知歌手',title:'未命名歌曲',genre:'cloud',scenes:[],duration:0,source:names[p],cover:''};if(p==='netease'){Object.assign(n,{mediaId:String(s.id),title:s.name,artist:(s.ar||s.artists||[]).map(x=>x.name).join(' / '),duration:(s.dt||s.duration||0)/1000,cover:secureUrl(s.al?.picUrl||s.album?.picUrl||'')})}else if(p==='qq'){const mid=s.mid||s.songmid||s.songMid;const album=s.album||{};Object.assign(n,{mediaId:String(mid||''),numericId:s.id||s.songid,title:s.name||s.songname||s.title,artist:(s.singer||s.artists||[]).map(x=>x.name).join(' / '),duration:s.interval||s.duration||0,cover:secureUrl(s.coverUrl||(album.mid||s.albummid?`https://y.gtimg.cn/music/photo_new/T002R500x500M000${album.mid||s.albummid}.jpg`:''))})}else if(p==='kugou'){let d=Number(s.Duration||s.duration||s.timelen||0);Object.assign(n,{mediaId:String(s.FileHash||s.hash||s.Hash||''),title:s.SongName||s.songname||s.FileName||s.name,artist:s.SingerName||s.singername||'未知歌手',duration:d>10000?d/1000:d,cover:secureUrl(String(s.Image||s.img||s.trans_param?.union_cover||'').replace('{size}','500')),albumId:s.AlbumID||s.album_id})}else if(p==='navidrome'){Object.assign(n,{mediaId:String(s.id),title:s.title,artist:s.artist,duration:s.duration,coverId:s.coverArt});n.cover=''}n.id=p+'-'+n.mediaId;return n}
function list(d){for(const v of [d?.items,d?.result?.songs,d?.data?.lists,d?.data?.info,d?.data?.songs,d?.data?.song?.list,d?.songs,d?.list,d?.info])if(Array.isArray(v))return v;return []}
async function search(p,query){if(p==='navidrome'){const d=await navRequest('search3',{query,songCount:30,artistCount:0,albumCount:0});return (d.searchResult3?.song||[]).map(s=>normalize(p,s))}const d=await request(p,p==='netease'?'/cloudsearch':'/search',p==='netease'?{keywords:query,limit:30}:p==='qq'?{keyword:query,type:'song',page:1,limit:20}:{keywords:query,keyword:query,type:'song',page:1,pagesize:30});return list(d).map(s=>normalize(p,s)).filter(s=>s.mediaId&&s.mediaId!=='undefined')}
async function getAudio(t,quality='standard'){const p=t.provider||(t.source==='网易云音乐'?'netease':null);if(!p)return {url:t.url};const id=t.mediaId||t.id.replace(/^cloud-/, '');let url,preview=false;if(p==='netease'){const d=await request(p,'/song/url/v1',{id,level:quality,https:true});const r=d.data?.[0];url=r?.url;preview=!!r?.freeTrialInfo&&typeof r.freeTrialInfo==='object'}else if(p==='qq'){const d=await request(p,'/getMusicPlay/'+encodeURIComponent(id),{quality:quality==='lossless'?'flac':quality==='standard'?'128':'320'});const entries=d.data?.playUrl||{};url=(entries[id]||Object.values(entries)[0])?.url}else if(p==='kugou'){const d=await request(p,'/song/url',{hash:id,album_id:t.albumId||'',quality:quality==='lossless'?'flac':'128'});const r=d.data||d;const urls=r.url||r.play_url||r.playUrl;url=Array.isArray(urls)?urls.find(x=>typeof x==='string'&&/^https?:/.test(x)):urls}else url=navUrl('stream',{id,maxBitRate:0});url=secureUrl(url);if(!url)throw Error('未取得可播放地址，请检查账号、歌曲权限与服务状态');return {url,preview}}
async function getLyrics(t){if(t.provider==='netease'||t.source==='网易云音乐'){const d=await request('netease','/lyric/new',{id:t.mediaId||t.id.replace(/^cloud-/, '')});return {format:d.yrc?.lyric?'yrc':'lrc',text:d.yrc?.lyric||d.lrc?.lyric||'',translation:d.tlyric?.lyric||''}}if(t.provider==='kugou'){const d=await request('kugou','/search/lyric',{hash:t.mediaId,duration:Math.round(t.duration*1000),man:'no'});const c=d.candidates?.[0]||d.data?.candidates?.[0];if(!c)return {text:''};const l=await request('kugou','/lyric',{id:c.id,accesskey:c.accesskey,fmt:'lrc',decode:true});return {format:'lrc',text:l.decodeContent||l.data?.decodeContent||''}}return {text:''}}
async function playlist(p,id){if(p==='netease'){const d=await request(p,'/playlist/track/all',{id,limit:1000,offset:0});if(!Array.isArray(d.songs))throw Error('歌单不存在或不可访问');return d.songs.map(s=>normalize(p,s))}if(p==='qq'){const d=await request(p,'/getSongListDetail/'+encodeURIComponent(id));const cd=d.response?.cdlist?.[0]||d.data?.cdlist?.[0];if(!cd||!Array.isArray(cd.songlist))throw Error('歌单不存在或不可访问');return cd.songlist.map(s=>normalize(p,s))}if(p==='navidrome'){const d=await navRequest('getPlaylist',{id});return (d.playlist?.entry||[]).map(s=>normalize(p,s))}throw Error('酷狗歌单导入暂未适配，可先搜索歌曲')}
async function test(p){if(p==='navidrome'){await navRequest('ping');return '已连接'}const d=await request(p,p==='kugou'?'/search':'/login/status',p==='kugou'?{keywords:'钢琴',type:'song',pagesize:1}:{});if(p==='netease')return d.data?.profile?.nickname?'已登录 · '+d.data.profile.nickname:'服务可达 · 未登录';if(p==='qq')return d.user||d.data?.user?'已登录':'服务可达';return '服务可达'}
async function qrStart(p){if(!['netease','qq'].includes(p))throw Error('此来源暂不提供扫码登录');const d=await request(p,'/login/qr/key',p==='qq'?{type:'qq'}:{});const key=d.data?.unikey||d.unikey||d.data?.key||d.key;if(!key)throw Error('服务未返回二维码密钥');const q=await request(p,'/login/qr/create',{key,qrimg:true,...(p==='qq'?{type:'qq'}:{})});const data=q.data||q;const image=data.qrimg||data.qrImage||data.qrimage;const qrurl=data.qrurl||data.url;if(!image)throw Error('服务未提供可显示的二维码，请检查 API 版本');if(!/^data:image\/(png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(image))throw Error('二维码格式不受支持');return {key,image,qrurl}}
async function qrCheck(p,key){const d=await request(p,'/login/qr/check',{key});if(Number(d.code)===803&&!d.cookie)throw Error('服务未返回可用登录态，请检查后端版本');if(Number(d.code)===803&&d.cookie){sessions[p]={cookie:d.cookie};if(p==='qq'){const token=d.cookie.split(';').map(s=>s.trim()).find(x=>x.startsWith('qqmusic_session='));sessions[p].token=token?.slice('qqmusic_session='.length)||d.token||''}}return {code:Number(d.code),message:d.message||'',loggedIn:Number(d.code)===803}}
// RFC 1321 MD5 for Subsonic's token authentication; passwords stay in memory.
function md5(text){const b=new TextEncoder().encode(text),n=Math.ceil((b.length+9)/64)*64,buf=new Uint8Array(n);buf.set(b);buf[b.length]=128;const view=new DataView(buf.buffer);view.setUint32(n-8,(b.length*8)>>>0,true);view.setUint32(n-4,Math.floor(b.length/0x20000000),true);let state=[0x67452301,0xefcdab89,0x98badcfe,0x10325476];const shifts=[7,12,17,22,5,9,14,20,4,11,16,23,6,10,15,21];for(let off=0;off<n;off+=64){let [a,b,c,d]=state;for(let i=0;i<64;i++){let f,k;if(i<16){f=(b&c)|(~b&d);k=i}else if(i<32){f=(d&b)|(~d&c);k=(5*i+1)%16}else if(i<48){f=b^c^d;k=(3*i+5)%16}else{f=c^(b|~d);k=(7*i)%16}const sum=(a+f+Math.floor(Math.abs(Math.sin(i+1))*2**32)+view.getUint32(off+4*k,true))|0,s=shifts[Math.floor(i/16)*4+i%4],next=(b+((sum<<s)|(sum>>>(32-s))))|0;a=d;d=c;c=b;b=next}state=state.map((v,i)=>(v+[a,b,c,d][i])|0)}return state.map(x=>[0,8,16,24].map(n=>((x>>>n)&255).toString(16).padStart(2,'0')).join('')).join('')}
function navLogin(username,password){if(!username||!password)throw Error('请填写 Navidrome 用户名和密码');const salt=Array.from(crypto.getRandomValues(new Uint8Array(12)),x=>x.toString(16).padStart(2,'0')).join('');sessions.navidrome={username,salt,token:md5(password+salt)}}
function navUrl(method,params={}){const auth=sessions.navidrome;if(!auth)throw Error('请先登录 Navidrome');const u=new URL(base('navidrome')+'/rest/'+method+'.view');Object.entries({u:auth.username,t:auth.token,s:auth.salt,v:'1.16.1',c:'Sonora',f:'json',...params}).forEach(([k,v])=>u.searchParams.set(k,String(v)));return u.href}
async function navRequest(method,params){const d=await json(navUrl(method,params));const r=d['subsonic-response'];if(!r||r.status!=='ok')throw Error(r?.error?.message||'Navidrome 未返回有效响应');return r}
function parseLyrics(text,format='lrc'){let offset=0;const m=text.match(/\[offset:([+-]?\d+)\]/i);if(m)offset=Number(m[1])/1000;const lines=[];for(const raw of text.split(/\r?\n/)){if(format==='yrc'){const h=raw.match(/^\[(\d+),(\d+)\](.*)$/);if(!h)continue;let words=[];for(const x of h[3].matchAll(/\((\d+),(\d+),\d+\)([^()]*)/g))words.push({start:+x[1]/1000,end:(+x[1]+ +x[2])/1000,text:x[3]});const full=words.map(w=>w.text).join('');if(full.trim())lines.push({start:+h[1]/1000,end:(+h[1]+ +h[2])/1000,text:full,words})}else{const times=[...raw.matchAll(/\[(\d+):(\d+(?:\.\d+)?)\]/g)];const content=raw.replace(/\[[^\]]*\]/g,'').trim();if(!content)continue;for(const x of times)lines.push({start:+x[1]*60+ +x[2]+offset,text:content,words:[]})}}lines.sort((a,b)=>a.start-b.start);for(let i=0;i<lines.length;i++)if(!Number.isFinite(lines[i].end))lines[i].end=lines[i+1]?.start??lines[i].start+8;return lines}
function atTime(lines,time){let lo=0,hi=lines.length-1,result=-1;while(lo<=hi){const m=(lo+hi)>>1;if(lines[m].start<=time){result=m;lo=m+1}else hi=m-1}return result}
global.MusicSources={names,configure,getConfig:p=>configs[p]||null,request,search,getAudio,getLyrics,playlist,test,qrStart,qrCheck,navLogin,logout:p=>delete sessions[p],getCover:t=>t.provider==='navidrome'&&t.coverId?navUrl('getCoverArt',{id:t.coverId,size:500}):t.cover,normalize,secureUrl,parseLyrics,atTime,md5};
})(window);
